for i,succs in pruned.items():
    if i not in pairs: continue
    for j in succs:
        if j not in pairs or j==i: continue
        for k in pruned.get(j,set()):
            if k in (i,j): continue
            if i in pruned.get(k,set()) and i<j and i<k:
                count3p+=1
chain1p=sum(len(s) for d,s in pruned.items() if d in altruists)
chain2p=0
chain3p=0
for a,succs in pruned.items():
    if a not in altruists: continue
    for p1 in succs:
        for p2 in pruned.get(p1,set()):
            if p2==p1: continue
            chain2p+=1
            for p3 in pruned.get(p2,set()):
                if p3 in (p1,p2): continue
                chain3p+=1
print('pruned totals', count2p, count3p, chain1p, chain2p, chain3p, 'total', count2p+count3p+chain1p+chain2p+chain3p)
